<template><div><div class="page-title"><div><div class="eyebrow">VULNERABILITY CENTER</div><h2>漏洞管理</h2></div></div><el-form inline class="section-card"><el-select v-model="severity" placeholder="严重性" clearable><el-option v-for="item in ['critical','high','medium','low']" :key="item" :label="item" :value="item"/></el-select><el-select v-model="status" placeholder="状态" clearable><el-option v-for="item in ['open','processing','fixed','ignored']" :key="item" :label="item" :value="item"/></el-select><el-button @click="load">查询</el-button></el-form><div v-loading="loading" class="table-wrap"><el-table :data="vulnerabilities"><el-table-column prop="title" label="漏洞"/><el-table-column prop="cve_id" label="CVE"/><el-table-column prop="severity" label="严重性"/><el-table-column prop="cvss_score" label="CVSS"/><el-table-column prop="status" label="状态"/><el-table-column prop="asset_id" label="资产 ID"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="detail(row)">详情</el-button><el-button link @click="changeStatus(row)">改状态</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!vulnerabilities.length" description="暂无漏洞记录"/></div><el-pagination v-if="total" class="section-card" layout="prev, pager, next" :page-size="10" :total="total" v-model:current-page="page" @current-change="load"/><el-drawer v-model="visible" title="漏洞详情" size="460px"><el-descriptions v-if="selected" :column="1" border><el-descriptions-item label="名称">{{selected.title}}</el-descriptions-item><el-descriptions-item label="CVE">{{selected.cve_id||'未关联'}}</el-descriptions-item><el-descriptions-item label="严重性">{{selected.severity}}</el-descriptions-item><el-descriptions-item label="CVSS">{{selected.cvss_score??'未评分'}}</el-descriptions-item><el-descriptions-item label="状态">{{selected.status}}</el-descriptions-item><el-descriptions-item label="修复建议">{{selected.remediation||'暂无'}}</el-descriptions-item></el-descriptions></el-drawer><el-dialog v-model="statusVisible" title="更新漏洞状态" width="360px"><el-select v-model="nextStatus" class="full-width"><el-option v-for="item in ['open','processing','fixed','ignored']" :key="item" :label="item" :value="item"/></el-select><template #footer><el-button @click="statusVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveStatus">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import { onMounted, ref } from "vue"; import { ElMessage } from "element-plus"; import client from "../api/client"; import type { Vulnerability } from "../api/types";
const vulnerabilities=ref<Vulnerability[]>([]),total=ref(0),page=ref(1),loading=ref(false),severity=ref(""),status=ref(""),selected=ref<Vulnerability|null>(null),visible=ref(false),statusVisible=ref(false),nextStatus=ref("open"),saving=ref(false);
const load=async()=>{loading.value=true;try{const r=(await client.get("/vulnerabilities",{params:{page:page.value,page_size:10,severity:severity.value||undefined,status:status.value||undefined}})).data;vulnerabilities.value=r.data;total.value=r.total;}catch{vulnerabilities.value=[];}finally{loading.value=false;}};const detail=(v:Vulnerability)=>{selected.value=v;visible.value=true};const changeStatus=(v:Vulnerability)=>{selected.value=v;nextStatus.value=v.status;statusVisible.value=true};const saveStatus=async()=>{if(!selected.value)return;saving.value=true;try{await client.patch(`/vulnerabilities/${selected.value.id}`,{status:nextStatus.value});ElMessage.success("状态已更新");statusVisible.value=false;load();}catch{ElMessage.error("更新失败");}finally{saving.value=false;}};onMounted(load);
</script>
